css:
 body{
    font-family:Arial, Helvetica, sans-serif;
  }
  @media print {
    @page {
        size: A5;/* Optional: Adjust margin as needed */
    }

}
.first-container {
  display: flex;
}
.first-container .Cash-reciept {
  border: 2px solid black;
  border-radius: 30px;
  height: 65px;
  padding: 10px 30px;
  text-align: center;
}
.first-container .paid-promotion h6 {
  border: 1px solid black;
  padding: 5px 10px;
  margin: 0;
  margin-top: -10px;
  font-size:10px;
}
.first-container .Date {
  display: flex;
  flex-direction: column;
  justify-content: end;
  gap: 10px;
}
.first-container .Date .first {
  height: 10px;
  display: flex;
  font-size: 12px;
  align-items: center;
  gap: 10px;
}
.first-container .Date .first strong {
  font-family: "Times New Roman", Georgia, serif;
}
.first-container .Date .second {
  height: 10px;
  display: flex;
  align-items: center;
  gap: 5px;
}
.first-container .Date .second .line {
width: 75px;
    height: 18px;
    border-bottom: 1px solid grey;
    margin-top:-8px;
    text-align: center;

}
.container-body {
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.container-body .line-div {
  display: flex;
  height: 20px;
  justify-content: space-between;
  align-items: center;
}
.container-body .line-div .line {
  border-bottom: 1px solid #d1d8dd;
  font-size: 10px;
  margin-top:-15px;
  width: 250px;
  text-align: center;
  font-weight: 600;
}
.container-body .line-div p {
  font-size: 12px;
}
.container-body .div7 {
  display: flex;
  margin-top:20px;
  align-items: center;
  justify-content: center;
  gap: 50px;
}
.container-body .div7 .accountant {
  gap: 30px;
  border-top: 1px solid black;
  display: flex;
}
.container-body .div7 .receiver {
  display: flex;
  gap: 30px;
  border-top: 1px solid black;
}
.container-body .new-line {
  display: flex;
  justify-content:space-between;
  align-items: center;
}
.container-body .new-line .text {
  width: 63%;
  display: flex;
  align-items: center;
  gap: 2px;
}
.container-body .new-line .text .line {
  border-bottom: 1px solid #868686;
  font-size: 12px;
  width: 100px;
  margin-top:-10px;
  text-align: center;
  font-weight: 600;
}
.container-body .new-line .text p {
  font-size: 12px;
}
.container-body .new-line .blue-line {
  height: 20px;
  background-color: #1a84b6;
  border-radius: 50px;
  width: 35%;
}

  html {
    direction: ltr;
 }
